import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Host Services","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/sdk/services.md","filePath":"dev-guide/sdk/services.md","lastUpdated":1784195945000}'),s={name:"dev-guide/sdk/services.md"};function d(i,e,c,n,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="host-services" tabindex="-1">Host Services <a class="header-anchor" href="#host-services" aria-label="Permalink to &quot;Host Services&quot;">​</a></h1><p>Static services in <code>PluginSdk.Services</code> that expose host-app functionality back to plugins — each is a thin static class wrapping a delegate the host wires up at startup, so plugins call them the same way regardless of what&#39;s running underneath.</p><table tabindex="0"><thead><tr><th>Service</th><th>Purpose</th></tr></thead><tbody><tr><td><code>FuzzyMatchService</code></td><td><code>IsMatch(pattern, text)</code> — whether <code>text</code> (or one of its aliases) matches an fzf-syntax <code>pattern</code>, using the exact same matching the host&#39;s own search uses; <code>GetHighlightMask(text, query)</code> — the per-character highlight mask for that pair, using the same literal/fuzzy/alias fallback tiers (including CJK pinyin) the host&#39;s own results highlight with, so a plugin&#39;s results highlight consistently instead of only handling a literal substring match.</td></tr><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> for runtime lookups against the active language; <code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> to load a plugin&#39;s own embedded JSON translations; <code>GetSupportedCultures(assembly)</code>; <code>GetCurrentCulture()</code> — the app&#39;s currently selected UI language (e.g. <code>&quot;zh-CN&quot;</code>), a user setting independent of the OS system locale. Reach for this only when you need the raw culture code itself (e.g. to put in an HTTP <code>Accept-Language</code> header or pick a translation API&#39;s target language) — <code>CultureInfo.CurrentUICulture</code> reflects the OS locale, not this setting, and will silently disagree with it whenever a user&#39;s Windows language and in-app language differ.</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> and <code>GetThumbnail(path, size)</code> — cached shell icon/thumbnail extraction, so a plugin never has to shell out to the Windows icon APIs itself.</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> — read-only access to the user&#39;s <a href="./../../user-guide/settings/favorites.html">Favorites</a> list (<code>FavoriteItem</code>: Name, Path).</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryEntries()</code> — every recorded <a href="./../../user-guide/settings/history.html">History</a> entry, most-recently-opened first, as <code>HistoryEntry { Keyword, Path, Kind, Time }</code> (<code>Kind</code> is a <code>HistoryEntryKind</code>: <code>File</code> / <code>Folder</code> / <code>Application</code>; <code>Keyword</code> is the search text that led to it, empty if opened directly from a Startup Panel tab with no query typed; <code>Time</code> is Unix seconds). Each path appears at most once, under whichever keyword most recently led to it.</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> — batched Size/Created/Modified/Accessed lookup (<a href="./abstractions.html#filemetadata"><code>FileMetadata</code></a>) for a path that <strong>isn&#39;t</strong> already one of your current results — every <code>ISearchResult</code> already carries this via its own <code>Metadata</code> property at no cost (see <a href="./abstractions.html#isearchresult">Abstractions</a>), so reach for this service only for paths you got some other way (e.g. from your own config).</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> / <code>NotifyDirectoryChanged(pluginId)</code> — lets a plugin register its own directories for background indexing and USN monitoring without reimplementing that machinery.</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> — read-only access to a plugin&#39;s own persisted settings from the host&#39;s config store. If you cache a setting instead of re-reading it every call, subscribe to the <code>SettingChanged(pluginId, key)</code> event and drop your cache when it fires for your plugin — the host raises it right after a settings-page save, which is the only reliable point to invalidate against (a per-keystroke or polling check will not see a change until whatever coincidentally triggers it next, or never).</td></tr><tr><td><code>SearchRefreshService</code></td><td><code>RefreshIfMatches(queryMatches)</code> — for an <code>IInstantResultProvider</code> whose data arrives asynchronously (see <a href="./core-search-actions.html#iinstantresultprovider"><code>IInstantResultProvider</code></a>): once your background fetch completes and you&#39;ve cached the result, call this with a predicate over a search&#39;s current query text, and the host re-runs every active search that predicate matches so the now-cached result actually appears without the user needing to retype anything.</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> — writes to the App&#39;s log file, visible in <strong>Settings → Service Status → App</strong> exactly like the host&#39;s own log lines.</td></tr></tbody></table><p><code>LogLevel</code> is <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>, matching the level filter in the <a href="./../../user-guide/settings/service-status.html">Service Status log viewer</a>.</p>',4)])])}const p=t(s,[["render",d]]);export{g as __pageData,p as default};
